                  <CheckCircle className="h-4 w-4 text-primary-light" />
                  <span className="text-white/90">{t('hero.open')}</span>
                </div>

                <h1 className="text-4xl md:text-7xl font-heading font-bold leading-[1.05] mb-6 tracking-tight">
                  {t('hero.title')}
                </h1>

                <p className="text-lg md:text-xl text-neutral-300 mb-10 max-w-xl leading-relaxed">
                  {t('hero.subtitle')}
                </p>

                <div className="flex flex-col sm:flex-row gap-5">
