                        </div>
                        <div>
                          <span className="block text-[10px] uppercase tracking-wider text-neutral-400 font-bold mb-0.5">{t('hero.info.phone')}</span>
                          <a href="tel:4054703232" className="hover:text-primary-light transition-colors font-semibold">(405) 470-3232</a>
                        </div>
                      </li>
                      <li className="flex items-center gap-3">
